documents.text:
query Catalogue {
  discover {
    products(order: {sku: ASC}) {
      nodes {
        sku
        name
        price
        stock
      }
    }
  }
}

query MyOrders {
  discover {
    orders {
      nodes {
        id
        total
        placedAt
      }
    }
  }
}

mutation PlaceOrder($input: PlaceOrderInput!) {
  dispatch {
    placeOrder(input: $input) {
      externalId
      output {
        orderId
        total
      }
    }
  }
}
